script:
test("returns the third absence date when a weekend gap does not break the streak", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("returns nothing when a present day resets the count before it reaches 3", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("returns the third absence date and ignores a fourth absence in the same streak", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("returns only the first date a streak reached 3 when two separate runs exist", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "present" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});

test("returns nothing for an empty list", function () {
  assert.equal(code.firstThreeDayAbsenceStreak([]), null);
});

test("returns nothing when no run of 3 consecutive absences exists", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});

test("returns the third date of a new streak after a present day resets the count", function () {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-11");
});

test("returns the third absence date when a removed holiday gap does not reset the streak", function () {
  var days = [
    { date: "2024-01-12", status: "absent" },
    { date: "2024-01-16", status: "absent" },
    { date: "2024-01-17", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-17");
});
